20	import { RectLike } from 'zrender/src/core/BoundingRect';
21	import type { CoordinateSystemDataLayout, NullUndefined, OrdinalNumber } from '../../util/types';
22	import {
23	    CoordinateSystem, CoordinateSystemMaster
24	} from '../CoordinateSystem';
25	import GlobalModel from '../../model/Global';
26	import ExtensionAPI from '../../core/ExtensionAPI';
27	import MatrixModel, {
28	    MatrixCoordRangeOption,
29	    MatrixDimensionCellOption, MatrixDimensionLevelOption, MatrixDimensionModel
30	} from './MatrixModel';
31	import { LayoutRect, getLayoutRect } from '../../util/layout';
32	import { ListIterator, ParsedModelFinder, ParsedModelFinderKnown } from '../../util/model';
33	import { eqNaN, isArray, retrieve2 } from 'zrender/src/core/util';
34	import Point from 'zrender/src/core/Point';
35	import { WH, XY } from '../../util/graphic';
36	import Model from '../../model/Model';
37	import type {
38	    MatrixCellLayoutInfo,
39	    MatrixDimensionCell, MatrixDimPair, MatrixXYLocator
40	} from './MatrixDim';
41	import { mathMax, mathMin, parsePositionSizeOption } from '../../util/number';
42	import {
43	    createNaNRectLike,
44	    MatrixClampOption,
45	    MatrixCellLayoutInfoType,
46	    parseCoordRangeOption,
47	    resetXYLocatorRange,
48	    xyLocatorRangeToRectOneDim
49	} from './matrixCoordHelper';
50	import type { MatrixBodyCorner, MatrixBodyOrCornerKind } from './MatrixBodyCorner';
51	import { error } from '../../util/log';
52	import { injectCoordSysByOption, simpleCoordSysInjectionProvider } from '../../core/CoordinateSystem';
53	
54	
55	class Matrix implements CoordinateSystem, CoordinateSystemMaster {
56	
57	    static readonly dimensions = ['x', 'y', 'value'];
58	    /**
59	     * @see fetchers in `model/referHelper.ts`,
60	     * which is used to parse data in ordinal way.
61	     * In most series only 'x' and 'y' is required,
62	     * but some series, such as heatmap, can specify value.
63	     */
64	    static getDimensionsInfo() {
65	        return [
66	            {name: 'x', type: 'ordinal' as const},
67	            {name: 'y', type: 'ordinal' as const},
68	            {name: 'value'},
69	        ];
70	    }
71	
72	    readonly dimensions = Matrix.dimensions;
73	    readonly type = 'matrix';
74	
75	    private _model: MatrixModel;
76	    private _dimModels: {
77	        x: MatrixDimensionModel;
78	        y: MatrixDimensionModel;
79	    };
80	    private _dims: MatrixDimPair;
81	
82	    private _rect: LayoutRect;
83	
84	    static create(ecModel: GlobalModel, api: ExtensionAPI) {
85	        const matrixList: Matrix[] = [];
86	
87	        ecModel.eachComponent('matrix', function (matrixModel: MatrixModel) {
88	            const matrix = new Matrix(matrixModel, ecModel, api);
89	            matrixList.push(matrix);
90	            matrixModel.coordinateSystem = matrix;
91	        });
92	
93	        // Inject coordinate system
94	        // PENDING: optimize to not to travel all components?
95	        //  (collect relevant components in ecModel only when model update?)
96	        ecModel.eachComponent((mainType, componentModel) => {
97	            injectCoordSysByOption({
98	                targetModel: componentModel,
99	                coordSysType: 'matrix',
100	                coordSysProvider: simpleCoordSysInjectionProvider,
101	            });
102	        });
103	
104	        return matrixList;
105	    }
106	
107	    constructor(matrixModel: MatrixModel, ecModel: GlobalModel, api: ExtensionAPI) {
108	        this._model = matrixModel;
109	        const models = this._dimModels = {
110	            x: matrixModel.getDimensionModel('x'),
111	            y: matrixModel.getDimensionModel('y'),
112	        };
113	        this._dims = {
114	            x: models.x.dim,
115	            y: models.y.dim,
116	        };
117	
118	        this._resize(matrixModel, api);
119	    }
120	
121	    getRect(): LayoutRect {
122	        return this._rect;
123	    }
124	
125	    private _resize(matrixModel: MatrixModel, api: ExtensionAPI) {
126	        const dims = this._dims;
127	        const dimModels = this._dimModels;
128	
129	        const rect = this._rect = getLayoutRect(matrixModel.getBoxLayoutParams(), {
130	            width: api.getWidth(),
131	            height: api.getHeight(),
132	        });
133	
134	        layOutUnitsOnDimension(dimModels, dims, rect, 0);
135	        layOutUnitsOnDimension(dimModels, dims, rect, 1);
136	
137	        layOutDimCellsRestInfoByUnit(0, dims);
138	        layOutDimCellsRestInfoByUnit(1, dims);
139	
140	        layOutBodyCornerCellMerge(this._model.getBody(), dims);
141	        layOutBodyCornerCellMerge(this._model.getCorner(), dims);
142	    }
143	
144	    /**
145	     * @implement
146	     * - The input is allowed to be `[NaN/null/undefined, xxx]`/`[xxx, NaN/null/undefined]`;
147	     *  the return is `[NaN, xxxresult]`/`[xxxresult, NaN]` or clamped boundary value if
148	     *  `clamp` passed. This is for the usage that only get coord on single x or y.
149	     * - Alwasy return an numeric array, but never be null/undefined.
150	     *  If it can not be located or invalid, return `[NaN, NaN]`.
151	     */
152	    dataToPoint(
153	        data: MatrixCoordRangeOption[],
154	        opt?: Parameters<Matrix['dataToLayout']>[1],
155	        out?: number[]
156	    ): number[] {
157	        out = out || [];
158	
159	        this.dataToLayout(data, opt, _dtpOutDataToLayout);
160	
161	        out[0] = _dtpOutDataToLayout.rect.x + _dtpOutDataToLayout.rect.width / 2;
162	        out[1] = _dtpOutDataToLayout.rect.y + _dtpOutDataToLayout.rect.height / 2;
163	        return out;
164	    }
165	
166	    /**
167	     * @implement
168	     * - The input is allowed to be `[NaN/null/undefined, xxx]`/`[xxx, NaN/null/undefined]`;
169	     *  the return is `{x: NaN, width: NaN, y: xxxresulty, height: xxxresulth}`/
170	     *  `{y: NaN, height: NaN, x: xxxresultx, width: xxxresultw}` or clamped boundary value
171	     *  if `clamp` passed. This is for the usage that only get coord on single x or y.
172	     * - The returned `out.rect` and `out.matrixXYLocatorRange` is always an object or an 2d-array,
173	     *  but never be null/undefined. If it cannot be located or invalid, `NaN` is in their
174	     *  corresponding number props.
175	     * - Do not provide `out.contentRect`, because it's allowed to input non-leaf dimension x/y or
176	     *  a range of x/y, which determines a rect covering multiple cells (even not merged), in which
177	     *  case the padding and borderWidth can not be determined to make a contentRect. Therefore only
178	     *  return `out.rect` in any case for consistency. The caller is responsible for adding space to
179	     *  avoid covering cell borders, if necessary.
180	     */
181	    dataToLayout(
182	        data: MatrixCoordRangeOption[],
183	        opt?: {
184	            // No clamp by default, considering the possibility of supporting dataZoom (overflow/scroll).
185	            clamp?: MatrixClampOption | NullUndefined;
186	            // Expand if cell merging is encountered.
187	            //  - `false`: If intersecting with a rect of merged cells, expand the result to cover it.
188	            //      This is the default option, becuase `series.data` do not support the format
189	            //      `MatrixCoordRangeOption` (e.g., `[[3,5], [5,8]]`), thus merged cells can only
190	            //      be located by single cell locators (e.g., `[3, 5]`).
191	            //  - `true`: regardless of cell merging, even if the resulting rect spans accorss the merged cells.
192	            ignoreMergeCells?: boolean;
193	        },
194	        out?: CoordinateSystemDataLayout
195	    ): CoordinateSystemDataLayout {
196	        const dims = this._dims;
197	
198	        out = out || {} as CoordinateSystemDataLayout;
199	        const outRect = out.rect = out.rect || {} as RectLike;
200	        outRect.x = outRect.y = outRect.width = outRect.height = NaN;
201	        const outLocRange = out.matrixXYLocatorRange = resetXYLocatorRange(out.matrixXYLocatorRange);
202	
203	        if (!isArray(data)) {
204	            if (__DEV__) {
205	                error('Input data must be an array in `convertToLayout`, `convertToPixel`');
206	            }
207	            return out;
208	        }
209	
210	        parseCoordRangeOption(
211	            outLocRange,
212	            null,
213	            data,
214	            dims,
215	            retrieve2(opt && opt.clamp, MatrixClampOption.none)
216	        );
217	
218	        if (!opt || !opt.ignoreMergeCells) {
219	            if (!opt || opt.clamp !== MatrixClampOption.corner) {
220	                this._model.getBody().expandRangeByCellMerge(outLocRange);
221	            }
222	            if (!opt || opt.clamp !== MatrixClampOption.body) {
223	                this._model.getCorner().expandRangeByCellMerge(outLocRange);
224	            }
225	        }
226	
227	        xyLocatorRangeToRectOneDim(outRect, outLocRange, dims, 0);
228	        xyLocatorRangeToRectOneDim(outRect, outLocRange, dims, 1);
229	
230	        return out;
231	    }
232	
233	    /**
234	     * The returned locator pair can be the input of `dataToPoint` or `dataToLayout`.
235	     *
236	     * If point[0] is out of the matrix rect,
237	     *  the out[0] is NaN;
238	     * else if it is on the right of top-left corner of body,
239	     *  the out[0] is the oridinal number (>= 0).
240	     * else
241	     *  out[0] is the locator for corner or header (<= 0).
242	     *
243	     * The same rule goes for point[1] and out[1].
244	     *
245	     * But point[0] and point[1] are calculated separately, i.e.,
246	     * the reuslt can be `[1, NaN]` or `[NaN, 1]` if only one dimension is out of boundary.
247	     *
248	     * @implement
249	     */
250	    pointToData(
251	        point: number[],
252	        opt?: {
253	            clamp?: MatrixClampOption | NullUndefined
254	        },
255	        out?: MatrixXYLocator[]
256	    ): MatrixXYLocator[] {
257	        const dims = this._dims;
258	        pointToDataOneDimPrepareCtx(_tmpCtxPointToData, 0, dims, point, opt && opt.clamp);
259	        pointToDataOneDimPrepareCtx(_tmpCtxPointToData, 1, dims, point, opt && opt.clamp);
260	
261	        out = out || [];
262	        out[0] = out[1] = NaN;
263	
264	        if (_tmpCtxPointToData.y === CtxPointToDataAreaType.inCorner
265	            && _tmpCtxPointToData.x === CtxPointToDataAreaType.inBody
266	        ) {
267	            pointToDataOnlyHeaderFillOut(_tmpCtxPointToData, out, 0, dims);
268	        }
269	        else if (_tmpCtxPointToData.x === CtxPointToDataAreaType.inCorner
270	            && _tmpCtxPointToData.y === CtxPointToDataAreaType.inBody
271	        ) {
272	            pointToDataOnlyHeaderFillOut(_tmpCtxPointToData, out, 1, dims);
273	        }
274	        else {
275	            pointToDataBodyCornerFillOut(_tmpCtxPointToData, out, 0, dims);
276	            pointToDataBodyCornerFillOut(_tmpCtxPointToData, out, 1, dims);
277	        }
278	
279	        return out;
280	    }
281	
282	    convertToPixel(
283	        ecModel: GlobalModel,
284	        finder: ParsedModelFinder,
285	        value: Parameters<Matrix['dataToPoint']>[0],
286	        opt?: Parameters<Matrix['dataToPoint']>[1],
287	    ): ReturnType<Matrix['dataToPoint']> | NullUndefined {
288	        const coordSys = getCoordSys(finder);
289	        return coordSys === this ? coordSys.dataToPoint(value, opt) : undefined;
290	    }
291	
292	    convertToLayout(
293	        ecModel: GlobalModel,
294	        finder: ParsedModelFinder,
295	        value: Parameters<Matrix['dataToLayout']>[0],
296	        opt?: Parameters<Matrix['dataToLayout']>[1],
297	    ): ReturnType<Matrix['dataToLayout']> | NullUndefined {
298	        const coordSys = getCoordSys(finder);
299	        return coordSys === this ? coordSys.dataToLayout(value, opt) : undefined;
300	    }
301	
302	    convertFromPixel(
303	        ecModel: GlobalModel,
304	        finder: ParsedModelFinder,
305	        pixel: Parameters<Matrix['pointToData']>[0],
306	        opt?: Parameters<Matrix['pointToData']>[1],
307	    ): ReturnType<Matrix['pointToData']> | NullUndefined {
308	        const coordSys = getCoordSys(finder);
309	        return coordSys === this ? coordSys.pointToData(pixel, opt) : undefined;
310	    }
311	
312	    containPoint(
313	        point: number[]
314	    ): boolean {
315	        return this._rect.contain(point[0], point[1]);
316	    }
317	
318	}
319	
320	const _dtpOutDataToLayout = {rect: createNaNRectLike()};
321	const _ptdLevelIt = new ListIterator<MatrixCellLayoutInfo>();
322	const _ptdDimCellIt = new ListIterator<MatrixDimensionCell>();
323	
324	
325	function layOutUnitsOnDimension(
326	    dimModels: Matrix['_dimModels'],
327	    dims: MatrixDimPair,
328	    matrixRect: RectLike,
329	    dimIdx: number
330	): void {
331	    const otherDimIdx = 1 - dimIdx;
332	    const thisDim = dims[XY[dimIdx]];
333	    const otherDim = dims[XY[otherDimIdx]];
334	    // Notice: If matrix.x/y.show is false, still lay out, to ensure the
335	    // consistent return of `dataToLayout`.
336	    const otherDimShow = otherDim.shouldShow();
337	
338	    // Reset
339	    for (const it = thisDim.resetCellIterator(); it.next();) {
340	        it.item.wh = it.item.xy = NaN;
341	    }
342	    for (const it = otherDim.resetLayoutIterator(null, dimIdx); it.next();) {
343	        it.item.wh = it.item.xy = NaN;
344	    }
345	
346	    // Set specified size from option.
347	    let restSize = matrixRect[WH[dimIdx]];
348	    let restCellsCount = thisDim.getLocatorCount(dimIdx) + otherDim.getLocatorCount(dimIdx);
349	    const tmpLevelModel = new Model<MatrixDimensionLevelOption>();
350	    for (const it = otherDim.resetLevelIterator(); it.next();) {
351	        // Consider `matrix.x.levelSize` and `matrix.x.levels[i].levelSize`.
352	        tmpLevelModel.option = it.item.option;
353	        tmpLevelModel.parentModel = dimModels[XY[otherDimIdx]];
354	        layOutSpecified(it.item, otherDimShow ? tmpLevelModel.get('levelSize') : 0);
355	    }
356	    const tmpCellModel = new Model<MatrixDimensionCellOption>();
357	    for (const it = thisDim.resetCellIterator(); it.next();) {
358	        // Only leaf support size specification, to avoid unnecessary complexity.
359	        if (it.item.type === MatrixCellLayoutInfoType.leaf) {
360	            tmpCellModel.option = it.item.option;
361	            tmpCellModel.parentModel = undefined;
362	            layOutSpecified(it.item, tmpCellModel.get('size'));
363	        }
364	    }
365	    function layOutSpecified(item: MatrixCellLayoutInfo, sizeOption: unknown): void {
366	        const size = parseSizeOption(sizeOption, dimIdx, matrixRect);
367	        if (!eqNaN(size)) {
368	            item.wh = confineSize(size, restSize);
369	            restSize = confineSize(restSize - item.wh);
370	            restCellsCount--;
371	        }
372	    }
373	
374	    // Set all sizes and positions to levels and leaf cells of which size is unspecified.
375	    // Contents lay out based on matrix, rather than inverse; therefore do not support
376	    // calculating size based on content, but allocate equally.
377	    const computedCellWH = restCellsCount ? (restSize / restCellsCount) : 0;
378	    // If all size specified, but some space remain (may also caused by matrix.x/y.show: false)
379	    // do not align to the big most edge.
380	    const notAlignToBigmost = !restCellsCount && restSize >= 1; // `1` for cumulative precision error.
381	    let currXY = matrixRect[XY[dimIdx]];
382	    const maxLocator = thisDim.getLocatorCount(dimIdx) - 1;
383	    const it = new ListIterator<MatrixCellLayoutInfo>();
384	
385	    // Lay out levels of the perpendicular dim.
386	    for (otherDim.resetLayoutIterator(it, dimIdx); it.next();) {
387	        layOutUnspecified(it.item);
388	    }
389	    for (thisDim.resetLayoutIterator(it, dimIdx); it.next();) {
390	        layOutUnspecified(it.item);
391	    }
392	    function layOutUnspecified(item: MatrixCellLayoutInfo) {
393	        if (eqNaN(item.wh)) {
394	            item.wh = computedCellWH;
395	        }
396	        item.xy = currXY;
397	        if (item.id[XY[dimIdx]] === maxLocator && !notAlignToBigmost) {
398	            // Align to the rightmost border, consider cumulative precision error.
399	            item.wh = matrixRect[XY[dimIdx]] + matrixRect[WH[dimIdx]] - item.xy;
400	        }
401	        currXY += item.wh;
402	    }
403	}
404	
405	function layOutDimCellsRestInfoByUnit(dimIdx: number, dims: MatrixDimPair): void {
406	    // Finally save layout info based on the unit leaves and levels.
407	    for (const it = dims[XY[dimIdx]].resetCellIterator(); it.next();) {
408	        const dimCell = it.item;
409	        layOutRectOneDimBasedOnUnit(dimCell.rect, dimIdx, dimCell.id, dimCell.span, dims);
410	        // Consider level varitation on tree leaves, should extend the size to touch matrix body
411	        // to avoid weird appearance.
412	        layOutRectOneDimBasedOnUnit(dimCell.rect, 1 - dimIdx, dimCell.id, dimCell.span, dims);
413	
414	        if (dimCell.type === MatrixCellLayoutInfoType.nonLeaf) {
415	            // `xy` and `wh` need to be saved in non-leaf since it supports locating by non-leaf
416	            // in `dataToPoint` or `dataToLayout`.
417	            dimCell.xy = dimCell.rect[XY[dimIdx]];
418	            dimCell.wh = dimCell.rect[WH[dimIdx]];
419	        }
420	    }
421	}
422	
423	function layOutBodyCornerCellMerge(bodyOrCorner: MatrixBodyCorner<MatrixBodyOrCornerKind>, dims: MatrixDimPair) {
424	    bodyOrCorner.travelExistingCells(cell => {
425	        const computedSpan = cell.span;
426	        if (computedSpan) {
427	            const layoutRect = cell.spanRect;
428	            const id = cell.id;
429	            layOutRectOneDimBasedOnUnit(layoutRect, 0, id, computedSpan, dims);
430	            layOutRectOneDimBasedOnUnit(layoutRect, 1, id, computedSpan, dims);
431	        }
432	    });
433	}
434	
435	// Save to rect for rendering.
436	function layOutRectOneDimBasedOnUnit(
437	    outRect: RectLike, dimIdx: number, id: Point, span: Point, dims: MatrixDimPair
438	): void {
439	    outRect[WH[dimIdx]] = 0;
440	    const locator = id[XY[dimIdx]];
441	    const dim = locator < 0 ? dims[XY[1 - dimIdx]] : dims[XY[dimIdx]];
442	    const layoutUnit = dim.getUnitLayoutInfo(dimIdx, id[XY[dimIdx]]);
443	    outRect[XY[dimIdx]] = layoutUnit.xy;
444	    outRect[WH[dimIdx]] = layoutUnit.wh;
445	
446	    if (span[XY[dimIdx]] > 1) {
447	        const layoutUnit2 = dim.getUnitLayoutInfo(dimIdx, id[XY[dimIdx]] + span[XY[dimIdx]] - 1);
448	        // Be careful the cumulative error - cell must be aligned.
449	        outRect[WH[dimIdx]] = layoutUnit2.xy + layoutUnit2.wh - layoutUnit.xy;
450	    }
451	}
452	
453	/**
454	 * Return NaN if not defined or invalid.
455	 */
456	function parseSizeOption(
457	    sizeOption: unknown,
458	    dimIdx: number,
459	    matrixRect: RectLike,
460	): number {
461	    const sizeNum = parsePositionSizeOption(sizeOption, matrixRect[WH[dimIdx]]);
462	    return confineSize(sizeNum, matrixRect[WH[dimIdx]]);
463	}
464	
465	function confineSize(
466	    sizeNum: number,
467	    sizeLimit?: number,
468	): number {
469	    return Math.max(Math.min(sizeNum, retrieve2(sizeLimit, Infinity)), 0);
470	}
471	
472	function getCoordSys(finder: ParsedModelFinderKnown): Matrix {
473	    const matrixModel = finder.matrixModel as MatrixModel;
474	    const seriesModel = finder.seriesModel;
475	
476	    const coordSys = matrixModel
477	        ? matrixModel.coordinateSystem
478	        : seriesModel
479	        ? seriesModel.coordinateSystem
480	        : null;
481	
482	    return coordSys as Matrix;
483	}
484	
485	const CtxPointToDataAreaType = {inBody: 1, inCorner: 2, outside: 3};
486	type CtxPointToDataAreaType = (typeof CtxPointToDataAreaType)[keyof typeof CtxPointToDataAreaType];
487	type CtxPointToData = {
488	    x: CtxPointToDataAreaType | NullUndefined;
489	    y: CtxPointToDataAreaType | NullUndefined;
490	    point: number[]; // If clamp required, this point is clamped after prepared.
491	};
492	// For handy performance optimization in pointToData.
493	const _tmpCtxPointToData: CtxPointToData = {x: null, y: null, point: []};
494	
495	function pointToDataOneDimPrepareCtx(
496	    ctx: CtxPointToData,
497	    dimIdx: number,
498	    dims: MatrixDimPair,
499	    point: number[],
500	    clamp: MatrixClampOption | NullUndefined
501	) {
502	    const thisDim = dims[XY[dimIdx]];
503	    const otherDim = dims[XY[1 - dimIdx]];
504	
505	    // Notice: considered cases: `matrix.x/y.show: false`, `matrix.x/y.data` is empty.
506	    // In this cases the `layout.xy` is on the edge and `layout.wh` is `0`; they still can be
507	    // use to calculate clampping.
508	
509	    const bodyMaxUnit = thisDim.getUnitLayoutInfo(dimIdx, thisDim.getLocatorCount(dimIdx) - 1);
510	    const body0Unit = thisDim.getUnitLayoutInfo(dimIdx, 0);
511	    const cornerMinUnit = otherDim.getUnitLayoutInfo(dimIdx, -otherDim.getLocatorCount(dimIdx));
512	    const cornerMinus1Unit = otherDim.shouldShow() ? otherDim.getUnitLayoutInfo(dimIdx, -1) : null;
513	
514	    let coord = ctx.point[dimIdx] = point[dimIdx]; // Transfer the oridinal coord.
515	
516	    if (!body0Unit && !cornerMinus1Unit) {
517	        ctx[XY[dimIdx]] = CtxPointToDataAreaType.outside;
518	        return;
519	    }
520	
521	    if (clamp === MatrixClampOption.body) {
522	        if (body0Unit) {
523	            ctx[XY[dimIdx]] = CtxPointToDataAreaType.inBody;
524	            coord = mathMin(bodyMaxUnit.xy + bodyMaxUnit.wh, mathMax(body0Unit.xy, coord));
525	            ctx.point[dimIdx] = coord;
526	        }
527	        else {
528	            // If clamp to body, the result must not be in header.
529	            ctx[XY[dimIdx]] = CtxPointToDataAreaType.outside;
530	        }
531	        return;
532	    }
533	    else if (clamp === MatrixClampOption.corner) {
534	        if (cornerMinus1Unit) {
535	            ctx[XY[dimIdx]] = CtxPointToDataAreaType.inCorner;
536	            coord = mathMin(cornerMinus1Unit.xy + cornerMinus1Unit.wh, mathMax(cornerMinUnit.xy, coord));
537	            ctx.point[dimIdx] = coord;
538	        }
539	        else {
540	            // If clamp to corner, the result must not be in body.
541	            ctx[XY[dimIdx]] = CtxPointToDataAreaType.outside;
542	        }
543	        return;
544	    }
545	
546	    const pxLoc0 = body0Unit ? body0Unit.xy : cornerMinus1Unit ? cornerMinus1Unit.xy + cornerMinus1Unit.wh : NaN;
547	    const pxMin = cornerMinUnit ? cornerMinUnit.xy : pxLoc0;
548	    const pxMax = bodyMaxUnit ? bodyMaxUnit.xy + bodyMaxUnit.wh : pxLoc0;
549	
550	    if (coord < pxMin) {
551	        if (!clamp) {
552	            // Quick pass for later calc, since mouse event on any place will enter this method if use `pointToData`.
553	            ctx[XY[dimIdx]] = CtxPointToDataAreaType.outside;
554	            return;
555	        }
556	        coord = pxMin;
557	    }
558	    else if (coord > pxMax) {
559	        if (!clamp) {
