45	export const MatrixClampOption = {
46	    // No clamp, be falsy, equals to null/undefined. It means if the input part is
47	    // null/undefined/NaN/outOfBoundary, the result part is NaN, rather than clamp to
48	    // the boundary of the matrix.
49	    none: 0,
50	    // Clamp, where null/undefined/NaN/outOfBoundary can be used to cover the entire row/column.
