667	            textStyle.backgroundColor = inheritColor;
668	        }
669	        if ((textStyle.borderColor === 'auto' || textStyle.borderColor === 'inherit') && inheritColor) {
670	            if (__DEV__) {
671	                if (textStyle.borderColor === 'auto') {
672	                    deprecateReplaceLog('borderColor: \'auto\'', 'borderColor: \'inherit\'');
673	                }
674	            }
675	            textStyle.borderColor = inheritColor;
676	        }
677	    }
