41	// When special border style is defined on cell, it
42	// should be over all of the other borders.
43	type Z2CellDefault = {normal: number, special: number};
44	const Z2_BACKGROUND = 0;
45	const Z2_OUTER_BORDER = 99;
46	const Z2_BODY_CORNER_CELL_DEFAULT: Z2CellDefault = {normal: 25, special: 100};
