211	function setLabelStyle<TLabelDataIndex>(
212	    targetEl: Element,
213	    labelStatesModels: LabelStatesModels<LabelModel>,
214	    opt?: SetLabelStyleOpt<TLabelDataIndex>,
215	    stateSpecified?: Partial<Record<DisplayState, TextStyleProps>>
216	    // TODO specified position?
217	) {
218	    opt = opt || EMPTY_OBJ;
219	    const isSetOnText = targetEl instanceof ZRText;
220	    let needsCreateText = false;
221	    for (let i = 0; i < DISPLAY_STATES.length; i++) {
222	        const stateModel = labelStatesModels[DISPLAY_STATES[i]];
223	        if (stateModel && stateModel.getShallow('show')) {
224	            needsCreateText = true;
225	            break;
226	        }
227	    }
228	    let textContent = isSetOnText ? targetEl as ZRText : targetEl.getTextContent();
229	    if (needsCreateText) {
230	        if (!isSetOnText) {
231	            // Reuse the previous
232	            if (!textContent) {
233	                textContent = new ZRText();
234	                targetEl.setTextContent(textContent);
235	            }
236	            // Use same state proxy
237	            if (targetEl.stateProxy) {
238	                textContent.stateProxy = targetEl.stateProxy;
239	            }
240	        }
241	        const labelStatesTexts = getLabelText(opt, labelStatesModels);
242	
243	        const normalModel = labelStatesModels.normal;
244	        const showNormal = !!normalModel.getShallow('show');
245	        const normalStyle = createTextStyle(
246	            normalModel, stateSpecified && stateSpecified.normal, opt, false, !isSetOnText
247	        );
248	        normalStyle.text = labelStatesTexts.normal;
249	        if (!isSetOnText) {
250	            // Always create new
251	            targetEl.setTextConfig(createTextConfig(normalModel, opt, false));
252	        }
253	
254	        for (let i = 0; i < SPECIAL_STATES.length; i++) {
255	            const stateName = SPECIAL_STATES[i];
256	            const stateModel = labelStatesModels[stateName];
257	
258	            if (stateModel) {
259	                const stateObj = textContent.ensureState(stateName);
260	                const stateShow = !!retrieve2(stateModel.getShallow('show'), showNormal);
261	                if (stateShow !== showNormal) {
262	                    stateObj.ignore = !stateShow;
263	                }
264	                stateObj.style = createTextStyle(
265	                    stateModel, stateSpecified && stateSpecified[stateName], opt, true, !isSetOnText
266	                );
267	                stateObj.style.text = labelStatesTexts[stateName];
268	
269	                if (!isSetOnText) {
270	                    const targetElEmphasisState = targetEl.ensureState(stateName);
271	                    targetElEmphasisState.textConfig = createTextConfig(stateModel, opt, true);
272	                }
273	            }
274	        }
275	
276	        // PENDING: if there is many requirements that emphasis position
277	        // need to be different from normal position, we might consider
278	        // auto silent is those cases.
279	        textContent.silent = !!normalModel.getShallow('silent');
280	        // Keep x and y
281	        if (textContent.style.x != null) {
282	            normalStyle.x = textContent.style.x;
283	        }
284	        if (textContent.style.y != null) {
285	            normalStyle.y = textContent.style.y;
286	        }
287	        textContent.ignore = !showNormal;
288	        // Always create new style.
289	        textContent.useStyle(normalStyle);
290	        textContent.dirty();
291	
292	        if (opt.enableTextSetter) {
293	            labelInner(textContent).setLabelText = function (interpolatedValue: InterpolatableValue) {
294	                const labelStatesTexts = getLabelText(opt, labelStatesModels, interpolatedValue);
295	                setLabelText(textContent, labelStatesTexts);
296	            };
297	        }
298	    }
299	    else if (textContent) {
300	        // Not display rich text.
301	        textContent.ignore = true;
302	    }
303	    targetEl.dirty();
304	}
