339	export function createTextConfig(
340	    textStyleModel: Model<LabelOption<{positionExtra: 'outside'}>>,
341	    opt?: Pick<
342	        TextCommonParams,
343	        'defaultOutsidePosition' | 'inheritColor' | 'autoOverflowArea' | 'layoutRect'
344	    >,
345	    isNotNormal?: boolean
346	) {
347	    opt = opt || {};
348	    const textConfig: ElementTextConfig = {};
349	    let labelPosition;
350	    let labelRotate = textStyleModel.getShallow('rotate');
351	    const labelDistance = retrieve2(textStyleModel.getShallow('distance'), isNotNormal ? null : 5);
352	    const labelOffset = textStyleModel.getShallow('offset');
353	    labelPosition = textStyleModel.getShallow('position')
354	        || (isNotNormal ? null : 'inside');
355	    // 'outside' is not a valid zr textPostion value, but used
356	    // in bar series, and magic type should be considered.
357	    labelPosition === 'outside' && (labelPosition = opt.defaultOutsidePosition || 'top');
358	    if (labelPosition != null) {
359	        textConfig.position = labelPosition;
360	    }
361	    if (labelOffset != null) {
362	        textConfig.offset = labelOffset;
363	    }
364	    if (labelRotate != null) {
365	        labelRotate *= Math.PI / 180;
366	        textConfig.rotation = labelRotate;
367	    }
368	    if (labelDistance != null) {
369	        textConfig.distance = labelDistance;
370	    }
371	    // fill and auto is determined by the color of path fill if it's not specified by developers.
372	    textConfig.outsideFill = textStyleModel.get('color') === 'inherit'
373	        ? (opt.inheritColor || null)
374	        : 'auto';
375	    if (opt.autoOverflowArea != null) {
376	        textConfig.autoOverflowArea = opt.autoOverflowArea;
377	    }
378	    if (opt.layoutRect != null) {
379	        textConfig.layoutRect = opt.layoutRect;
380	    }
381	    return textConfig;
382	}
