396	    textStyle: TextStyleProps,
397	    textStyleModel: LabelCommonModel<TNuance>,
398	    opt?: Pick<
399	        TextCommonParams,
400	        'inheritColor' | 'defaultOpacity' | 'disableBox' | 'defaultTextMargin'
401	    >,
402	    isNotNormal?: boolean,
403	    isAttached?: boolean
404	) {
405	    // Consider there will be abnormal when merge hover style to normal style if given default value.
406	    opt = opt || EMPTY_OBJ;
407	    const ecModel = textStyleModel.ecModel;
408	    const globalTextStyle = ecModel && ecModel.option.textStyle;
409	    // Consider case:
410	    // {
411	    //     data: [{
412	    //         value: 12,
413	    //         label: {
414	    //             rich: {
415	    //                 // no 'a' here but using parent 'a'.
416	    //             }
417	    //         }
418	    //     }],
419	    //     rich: {
420	    //         a: { ... }
421	    //     }
422	    // }
423	    const richItemNames = getRichItemNames<TNuance>(textStyleModel);
424	    let richResult: TextStyleProps['rich'];
425	    if (richItemNames) {
426	        richResult = {};
427	        const richInheritPlainLabelOptionName = 'richInheritPlainLabel' as const;
428	        const richInheritPlainLabel: boolean = retrieve2(
429	            textStyleModel.get(richInheritPlainLabelOptionName as any),
430	            ecModel ? ecModel.get(richInheritPlainLabelOptionName) : undefined
431	        );
432	        for (const name in richItemNames) {
433	            if (richItemNames.hasOwnProperty(name)) {
434	                // Cascade is supported in rich.
435	                const richTextStyle = textStyleModel.getModel(['rich', name]) as LabelCommonModel<TNuance>;
436	                // In rich, never `disableBox`.
437	                // consider `label: {formatter: '{a|xx}', color: 'blue', rich: {a: {}}}`,
438	                // the default color `'blue'` will not be adopted if no color declared in `rich`.
439	                // That might confuses users. So probably we should put `textStyleModel` as the
440	                // root ancestor of the `richTextStyle`. But that would be a break change.
