137	    getModel<R extends keyof Opt>(
138	        path: R, parentModel?: Model
139	    ): Model<Opt[R]>;
140	    getModel<R extends keyof Opt>(
141	        path: readonly [R], parentModel?: Model
142	    ): Model<Opt[R]>;
143	    getModel<R extends keyof Opt, S extends keyof Opt[R]>(
144	        path: readonly [R, S], parentModel?: Model
