49	export interface MatrixBodyCornerCell {
50	    // Represents col/row, serves as both id and locator.
51	    // Actually its `x` is `xDimCell.id.x`; its `y` is `yDimCell.id.y`
52	    id: Point;
53	    // raw option in `matrix.body/corner.data[i]`.
54	    option: MatrixBodyCornerCellOption | NullUndefined;
55	    // `matrix.body/corner.data[i].coord` can locate a rect of cells (say, area).
56	    // `inSpanOf` refers to the top-left cell, which represents that area.
57	    // The top-left cell has `inSpanOf` refering to itself.
58	    inSpanOf: MatrixBodyCornerCell | NullUndefined;
59	    // If existing, it indicates cell merging, and this cell is the top-left cell
60	    // of the merging area.
61	    cellMergeOwner: boolean;
62	    // Exist only if `cellMergeOwner: true`.
63	    // In this case, it enusres that x > 1 and y > 1 and never out of boundary;
64	    // othewise it is null/undefined.
65	    span: Point | NullUndefined;
66	    // Exist only if `cellMergeOwner: true`.
67	    // Convey the same info with `id`+`span`, but be used in different calculation.
68	    locatorRange: MatrixXYLocatorRange | NullUndefined;
69	    // Exist only if `cellMergeOwner: true`.
70	    spanRect: RectLike | NullUndefined;
