448	        return `${dimUpper}${dupBase++}`;
449	    }
450	
451	    // Duplicated value is allowed, because the `matrix.x/y.data` can be a tree and it's reasonable
452	    // that leaves in different subtrees has the same text. But only the first one is allowed to be
453	    // queried by the text, and the other ones can only be queried by index.
454	    // Additionally, `matrix.x/y.data: [null, null, ...]` is allowed.
455	    function ensureValueUnique(categories: (string | NullUndefined)[], cells: MatrixDimensionCell[]): void {
456	        // A simple way to deduplicate or handle illegal or not specified values to avoid unexpected behaviors.
457	        // The tree structure should not be broken even if duplicated.
458	        const cateMap = createHashMap<true, string>();
459	        for (let idx = 0; idx < categories.length; idx++) {
460	            let value = categories[idx];
461	            // value may be set to NullUndefined by users or if illegal.
462	            if (value == null || cateMap.get(value) != null) {
463	                // Still display the original option.value if duplicated, but loose the ability to query by text.
464	                categories[idx] = value = makeUniqueValue();
465	                cells[idx].option = defaults({value}, cells[idx].option);
466	            }
467	            cateMap.set(value, true);
468	        }
469	    }
470	
471	    return {calcDupBase, ensureValueUnique};
472	}
